    typealias SwiftType = CoreError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> CoreError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .BadReference(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 2: return .UnknownAction(
            reference: try FfiConverterString.read(from: &buf)
            )
        case 3: return .UnsupportedAction(
            reference: try FfiConverterString.read(from: &buf)
            )
        case 4: return .UnavailableOrigin(
            origin: try FfiConverterString.read(from: &buf)
