        switch value {

        

        
        
        case let .BadReference(detail):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(detail, into: &buf)
            
        
        case let .UnknownAction(reference):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(reference, into: &buf)
            
        
        case let .UnsupportedAction(reference):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(reference, into: &buf)
            
        
        case let .UnavailableOrigin(origin):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(origin, into: &buf)
            
        
        case let .Transport(detail):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(detail, into: &buf)
            
        
        case .NoListener:
            writeInt(&buf, Int32(6))
        
        
